import { fetchUsers } from '../api/users';

export async function getStats() {
  const users = await fetchUsers();
  const usr_cnt = users.length;
  const active = users.filter(u => u.active).length;
  return {
    usr_cnt,
    active,
    ratio: usr_cnt ? active / usr_cnt : 0,
  };
}

export function formatStats(s: { usr_cnt: number; active: number }) {
  return `${s.active} / ${s.usr_cnt} active`;
}
